package net.minecraft.world.item;import java.util.*;public class ItemStack{public static final ItemStack EMPTY=new ItemStack(new Item("minecraft:air"),0);public Item item;public int count;public String gun="tacz:pistol";public Map<Object,Object> data=new HashMap<>();public ItemStack(net.minecraft.world.level.ItemLike item,int n){this.item=(Item)item;count=n;}public Item getItem(){return item;}public int getCount(){return count;}public void setCount(int n){count=n;}public boolean isEmpty(){return count<=0||item.id.equals("minecraft:air");}public void grow(int n){count+=n;}public void shrink(int n){count-=n;}public int getMaxStackSize(){return item.getDefaultMaxStackSize();}public boolean isDamageableItem(){return item.id.contains("_axe")||item.id.contains("_pickaxe");}public int getMaxDamage(){return 200;}public void setDamageValue(int n){data.put("damage",n);}public Object set(Object key,Object value){return data.put(key,value);}public ItemStack copy(){ItemStack s=new ItemStack(item,count);s.data.putAll(data);s.gun=gun;return s;}public ItemStack copyWithCount(int n){ItemStack s=copy();s.count=n;return s;}public static boolean isSameItemSameComponents(ItemStack a,ItemStack b){return a.item.id.equals(b.item.id)&&a.data.equals(b.data)&&a.gun.equals(b.gun);}}
